"""Real baseline JPEGs (made with macOS sips, 64x48, quality 85) for brightness tests.

The scan data is genuine entropy-coded pixels, unlike the header-only fake JPEGs
used elsewhere, so app/services/thumbnail_brightness.py has something to decode.
"""

import base64
import struct
import zlib
from collections.abc import Callable

BLACK_JPEG = base64.b64decode(
    ""
)
WHITE_JPEG = base64.b64decode(
    ""
)
GRAD_JPEG = base64.b64decode(
    ""
)
DARK_JPEG = base64.b64decode(
    ""
)


def make_png(
    width: int,
    height: int,
    pixel: Callable[[int, int], tuple[int, ...]],
    *,
    color_type: int = 2,
    interlace: int = 0,
    filter_type: int = 0,
) -> bytes:
    """A real 8-bit PNG; filter_type applies one PNG filter to every row."""
    channels = {0: 1, 2: 3, 4: 2, 6: 4}[color_type]
    rows = []
    prev = bytes(width * channels)
    for y in range(height):
        row = bytes(v for x in range(width) for v in pixel(x, y))
        rows.append(bytes([filter_type]) + _filter(row, prev, channels, filter_type))
        prev = row

    def chunk(kind: bytes, data: bytes) -> bytes:
        crc = zlib.crc32(kind + data) & 0xFFFFFFFF
        return struct.pack(">I", len(data)) + kind + data + struct.pack(">I", crc)

    header = struct.pack(">IIBBBBB", width, height, 8, color_type, 0, 0, interlace)
    return (
        b"\x89PNG\r\n\x1a\n"
        + chunk(b"IHDR", header)
        + chunk(b"IDAT", zlib.compress(b"".join(rows)))
        + chunk(b"IEND", b"")
    )


def _filter(row: bytes, prev: bytes, bpp: int, filter_type: int) -> bytes:
    if filter_type == 0:
        return row
    out = bytearray()
    for i, value in enumerate(row):
        left = row[i - bpp] if i >= bpp else 0
        up = prev[i]
        up_left = prev[i - bpp] if i >= bpp else 0
        if filter_type == 1:
            predictor = left
        elif filter_type == 2:
            predictor = up
        elif filter_type == 3:
            predictor = (left + up) // 2
        else:  # 4: Paeth
            p = left + up - up_left
            pa, pb, pc = abs(p - left), abs(p - up), abs(p - up_left)
            predictor = left if pa <= pb and pa <= pc else up if pb <= pc else up_left
        out.append((value - predictor) % 256)
    return bytes(out)
